import{c as e,Q as i,j as t,m as n}from"./chunks/framework.CHJbb1iY.js";const r="/my-knowledge/assets/Linux%E5%9B%BE%E6%A0%87.IwSwPQap.png",o="/my-knowledge/assets/%E4%B8%BB%E6%B5%81%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F.CSSZajCZ.png",l="/my-knowledge/assets/%E5%8F%91%E8%A1%8C%E7%89%88.DPCOqurW.png",s="/my-knowledge/assets/linux%E7%9B%AE%E5%BD%95%E7%BB%93%E6%9E%84-1.Baj5x7NM.png",u="/my-knowledge/assets/linux%E7%9B%AE%E5%BD%95%E7%BB%93%E6%9E%84-2.BoQeTc9w.png",p=JSON.parse('{"title":"","description":"","frontmatter":{"sidebar":true,"aside":"right","outline":[2,3]},"headers":[],"relativePath":"docs/后端/DevOps/Linux/1. 基本介绍.md","filePath":"docs/后端/DevOps/Linux/1. 基本介绍.md"}'),h={name:"docs/后端/DevOps/Linux/1. 基本介绍.md"};function d(x,a,c,m,b,_){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 style="text-align:center;">基本介绍</h1><hr><h2 id="相关资料" tabindex="-1">相关资料 <a class="header-anchor" href="#相关资料" aria-label="Permalink to &quot;相关资料&quot;">​</a></h2><blockquote><h3><a href="https://pan.baidu.com/s/19dQ52S_ncXCujQ7tGRXVbg?pwd=xvxf" target="_blank">https://pan.baidu.com/s/19dQ52S_ncXCujQ7tGRXVbg?pwd=xvxf</a> 提取码: xvxf</h3></blockquote><h2 id="基本介绍" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h2><img src="'+r+'" style="width:300px;margin:auto;"><h4 id="linux-是一套免费使用和自由传播的操作系统。说到操作系统-大家比较熟知的应该就是-windows-和-macos-操作系统-我们今天所学习的-linux-也是一款操作系统" tabindex="-1">Linux 是一套免费使用和自由传播的操作系统。说到操作系统，大家比较熟知的应该就是 Windows 和 MacOS 操作系统，我们今天所学习的 Linux 也是一款操作系统 <a class="header-anchor" href="#linux-是一套免费使用和自由传播的操作系统。说到操作系统-大家比较熟知的应该就是-windows-和-macos-操作系统-我们今天所学习的-linux-也是一款操作系统" aria-label="Permalink to &quot;Linux 是一套免费使用和自由传播的操作系统。说到操作系统，大家比较熟知的应该就是 Windows 和 MacOS 操作系统，我们今天所学习的 Linux 也是一款操作系统&quot;">​</a></h4><h4 id="我们作为-javaee-开发工程师-将来在企业中开发时会涉及到很多的数据库、中间件等技术-比如-mysql、redis、mq-等技术-而这些应用软件大多都是需要安装在-linux-系统中使用的。我们做为开发人员-是需要通过远程工具连接-linux-操作系统-然后来操作这些软件的。而且一些小公司-可能还需要我们自己在服务器上安装这些软件" tabindex="-1">我们作为 javaEE 开发工程师，将来在企业中开发时会涉及到很多的数据库、中间件等技术，比如 MySQL、Redis、MQ 等技术，而这些应用软件大多都是需要安装在 Linux 系统中使用的。我们做为开发人员，是需要通过远程工具连接 Linux 操作系统，然后来操作这些软件的。而且一些小公司，可能还需要我们自己在服务器上安装这些软件 <a class="header-anchor" href="#我们作为-javaee-开发工程师-将来在企业中开发时会涉及到很多的数据库、中间件等技术-比如-mysql、redis、mq-等技术-而这些应用软件大多都是需要安装在-linux-系统中使用的。我们做为开发人员-是需要通过远程工具连接-linux-操作系统-然后来操作这些软件的。而且一些小公司-可能还需要我们自己在服务器上安装这些软件" aria-label="Permalink to &quot;我们作为 javaEE 开发工程师，将来在企业中开发时会涉及到很多的数据库、中间件等技术，比如 MySQL、Redis、MQ 等技术，而这些应用软件大多都是需要安装在 Linux 系统中使用的。我们做为开发人员，是需要通过远程工具连接 Linux 操作系统，然后来操作这些软件的。而且一些小公司，可能还需要我们自己在服务器上安装这些软件&quot;">​</a></h4><h4 id="所以-不管从企业的用人需求层面-还是个人发展需要层面来讲-我们作为服务端开发工程师-linux-的基本使用是我们必不可少的技能" tabindex="-1">所以，不管从企业的用人需求层面，还是个人发展需要层面来讲，我们作为服务端开发工程师，Linux 的基本使用是我们必不可少的技能 <a class="header-anchor" href="#所以-不管从企业的用人需求层面-还是个人发展需要层面来讲-我们作为服务端开发工程师-linux-的基本使用是我们必不可少的技能" aria-label="Permalink to &quot;所以，不管从企业的用人需求层面，还是个人发展需要层面来讲，我们作为服务端开发工程师，Linux 的基本使用是我们必不可少的技能&quot;">​</a></h4><h4 id="对于-linux-的常用指令的学习-最好的学习方法就是-多敲" tabindex="-1">对于 Linux 的常用指令的学习，最好的学习方法就是：<span style="color:red;">多敲</span> <a class="header-anchor" href="#对于-linux-的常用指令的学习-最好的学习方法就是-多敲" aria-label="Permalink to &quot;对于 Linux 的常用指令的学习，最好的学习方法就是：&lt;span style=&quot;color:red;&quot;&gt;多敲&lt;/span&gt;&quot;">​</a></h4><h2 id="主流操作系统" tabindex="-1">主流操作系统 <a class="header-anchor" href="#主流操作系统" aria-label="Permalink to &quot;主流操作系统&quot;">​</a></h2><h4 id="不同领域的主流操作系统-主要分为以下这么几类-桌面操作系统、服务器操作系统、移动设备操作系统、嵌入式操作系统" tabindex="-1">不同领域的主流操作系统，主要分为以下这么几类： 桌面操作系统、服务器操作系统、移动设备操作系统、嵌入式操作系统 <a class="header-anchor" href="#不同领域的主流操作系统-主要分为以下这么几类-桌面操作系统、服务器操作系统、移动设备操作系统、嵌入式操作系统" aria-label="Permalink to &quot;不同领域的主流操作系统，主要分为以下这么几类： 桌面操作系统、服务器操作系统、移动设备操作系统、嵌入式操作系统&quot;">​</a></h4><br><img src="'+o+'" style="width:800px;margin:auto;"><h2 id="linux-系统版本" tabindex="-1">Linux 系统版本 <a class="header-anchor" href="#linux-系统版本" aria-label="Permalink to &quot;Linux 系统版本&quot;">​</a></h2><h3 id="内核版" tabindex="-1">内核版 <a class="header-anchor" href="#内核版" aria-label="Permalink to &quot;内核版&quot;">​</a></h3><blockquote><h4 id="_1-由-linus-torvalds-及其团队开发、维护" tabindex="-1">（1）由 Linus Torvalds 及其团队开发、维护 <a class="header-anchor" href="#_1-由-linus-torvalds-及其团队开发、维护" aria-label="Permalink to &quot;（1）由 Linus Torvalds 及其团队开发、维护&quot;">​</a></h4><h4 id="_2-免费、开源" tabindex="-1">（2）免费、开源 <a class="header-anchor" href="#_2-免费、开源" aria-label="Permalink to &quot;（2）免费、开源&quot;">​</a></h4><h4 id="_3-负责控制硬件" tabindex="-1">（3）负责控制硬件 <a class="header-anchor" href="#_3-负责控制硬件" aria-label="Permalink to &quot;（3）负责控制硬件&quot;">​</a></h4></blockquote><h3 id="发行版" tabindex="-1">发行版 <a class="header-anchor" href="#发行版" aria-label="Permalink to &quot;发行版&quot;">​</a></h3><blockquote><h4 id="_1-基于-linux-内核版进行扩展" tabindex="-1">（1）基于 Linux 内核版进行扩展 <a class="header-anchor" href="#_1-基于-linux-内核版进行扩展" aria-label="Permalink to &quot;（1）基于 Linux 内核版进行扩展&quot;">​</a></h4><h4 id="_2-由各个-linux-厂商开发、维护" tabindex="-1">（2）由各个 Linux 厂商开发、维护 <a class="header-anchor" href="#_2-由各个-linux-厂商开发、维护" aria-label="Permalink to &quot;（2）由各个 Linux 厂商开发、维护&quot;">​</a></h4><h4 id="_3-有收费版本和免费版本" tabindex="-1">（3）有收费版本和免费版本 <a class="header-anchor" href="#_3-有收费版本和免费版本" aria-label="Permalink to &quot;（3）有收费版本和免费版本&quot;">​</a></h4></blockquote><h4 id="以下列举示-linux-的一些主流发行版" tabindex="-1">以下列举示 Linux 的一些主流发行版 <a class="header-anchor" href="#以下列举示-linux-的一些主流发行版" aria-label="Permalink to &quot;以下列举示 Linux 的一些主流发行版&quot;">​</a></h4><br><img src="'+l+'" style="width:800px;margin:auto;"><h2 id="linux-目录结构" tabindex="-1">Linux 目录结构 <a class="header-anchor" href="#linux-目录结构" aria-label="Permalink to &quot;Linux 目录结构&quot;">​</a></h2><br><img src="'+s+'" style="width:800px;margin:auto;"><br><img src="'+u+'" style="width:500px;">',27)])])}const k=e(h,[["render",d]]);export{p as __pageData,k as default};
